# --- types ---


class AxisAlignerPlan(_FrozenBase):
    pattern: Pair[Optional[str]]  # einops pattern per side, None = no-op


# --- planner ---


def compute_axis_aligner_plan(
    pair: Pair[Optional[str]],
) -> Optional[AxisAlignerPlan]:
    if pair.x is None or pair.y is None:
        return None

    specs_pair: Pair[list[DimSpec]] = Pair(
        x=parse_dims(pair.x).dims,
        y=parse_dims(pair.y).dims,
    )

    # Non-squeeze leaf (sub-dim) names; fused dims contribute their sub-dims.
    x_leaves: list[str] = _leaf_names(specs_pair.x)
    y_leaves: list[str] = _leaf_names(specs_pair.y)

    if set(x_leaves) != set(y_leaves):
        _warn_dim_mismatch(x_leaves, y_leaves)
        return None

    # Fused groups declared on each side, keyed by their sub-dim membership.
    x_groups: list[frozenset[str]] = _fused_group_keys(specs_pair.x)
    y_groups: list[frozenset[str]] = _fused_group_keys(specs_pair.y)

    if _has_overlapping_conflict(x_groups, y_groups):
        _warn_fused_conflict(x_groups, y_groups)
        return None

    # Canonical ordered sub-dims per fused group (prefer the x side when both fuse it).
    group_order: dict[frozenset[str], list[str]] = {}
    for spec in [*specs_pair.x, *specs_pair.y]:
        if spec.is_fused:
            group_order.setdefault(frozenset(spec.sub_dims), list(spec.sub_dims))

    leaf_to_group: dict[str, frozenset[str]] = {}
    for key in group_order:
        for leaf in key:
            leaf_to_group[leaf] = key
    for leaf in x_leaves:
        leaf_to_group.setdefault(leaf, frozenset([leaf]))

    # Target group order follows the y side (the reference layout).
    target_order: list[frozenset[str]] = []
    for spec in specs_pair.y:
        if _SingletonDimUtil.is_squeeze(spec):
            continue
        key = leaf_to_group[spec.sub_dims[0]]
        if key not in target_order:
            target_order.append(key)

    pattern: Pair[Optional[str]] = specs_pair.map(
        lambda specs: _build_pattern(
            specs=specs, target_order=target_order, group_order=group_order
        )
    )

    if pattern.x is None and pattern.y is None:
        return None

    return AxisAlignerPlan(pattern=pattern)


def _leaf_names(specs: list[DimSpec]) -> list[str]:
    return [
        sub
        for spec in specs
        if not _SingletonDimUtil.is_squeeze(spec)
        for sub in spec.sub_dims
    ]


def _fused_group_keys(specs: list[DimSpec]) -> list[frozenset[str]]:
    return [frozenset(spec.sub_dims) for spec in specs if spec.is_fused]


def _has_overlapping_conflict(
    x_groups: list[frozenset[str]], y_groups: list[frozenset[str]]
) -> bool:
    """A fused group on one side partially overlaps a fused group on the other."""
    for gx in x_groups:
        for gy in y_groups:
            if gx & gy and gx != gy:
                return True
    return False


def _build_pattern(
    *,
    specs: list[DimSpec],
    target_order: list[frozenset[str]],
    group_order: dict[frozenset[str], list[str]],
) -> Optional[str]:
    """Build an einops rearrange (and optional flatten) pattern for one side.

    Returns None if this side's physical layout already matches the target.
    """
    lhs: list[str] = []
    for spec in specs:
        if _SingletonDimUtil.is_squeeze(spec):
            lhs.append(spec.name)  # "1"
        else:
            lhs.append(spec.sanitized_name)

    this_fused: dict[frozenset[str], list[str]] = {
        frozenset(spec.sub_dims): list(spec.sub_dims)
        for spec in specs
        if spec.is_fused
    }

    rhs: list[str] = []
    for key in target_order:
        if len(key) == 1:
            (leaf,) = tuple(key)
            rhs.append(leaf)
        elif key in this_fused:
            # Already fused on this side -> emit the single joined axis label.
            rhs.append(FUSED_NAME_SEPARATOR.join(this_fused[key]))
        else:
            # Separate on this side -> flatten in the canonical sub-dim order.
            rhs.append("(" + " ".join(group_order[key]) + ")")

    if lhs == rhs:
        return None

    return f"{' '.join(lhs)} -> {' '.join(rhs)}"


def _warn_dim_mismatch(x_names: list[str], y_names: list[str]) -> None:
    # Local import to avoid circular dependency:
    # output_types -> aligner/entrypoint/types -> axis_aligner -> output_types
    from sglang.srt.debug_utils.comparator.output_types import ErrorLog

    log_sink.add(
        ErrorLog(
            category="axis_aligner_dim_mismatch",
            message=(
                f"AxisAligner: dim name sets differ (x={x_names}, y={y_names}), "
                f"skipping axis swap"
            ),
        )
    )


def _warn_fused_conflict(
    x_groups: list[frozenset[str]], y_groups: list[frozenset[str]]
) -> None:
    from sglang.srt.debug_utils.comparator.output_types import ErrorLog

    x_repr = [sorted(g) for g in x_groups]
    y_repr = [sorted(g) for g in y_groups]
    log_sink.add(
        ErrorLog(
            category="axis_aligner_fused_conflict",
            message=(
                f"AxisAligner: overlapping fused groups across sides "
                f"(x={x_repr}, y={y_repr}), skipping axis swap"
            ),
        )
    )


# --- executor ---


def execute_axis_aligner_plan(
    tensor: torch.Tensor, plan: AxisAlignerPlan, *, side: str
) -> torch.Tensor:
    if side not in ("x", "y"):
        raise ValueError(f"side must be 'x' or 'y', got {side!r}")

    pattern: Optional[str] = plan.pattern.x if side == "x" else plan.pattern.y

    if pattern is not None:
        tensor = rearrange(tensor.rename(None), pattern)

    return tensor
